extra_css:
:root:not([data-style]) .style-fx::before,
:root:not([data-style]) .style-fx::after,
:root[data-style='soft'] .style-fx::before,
:root[data-style='soft'] .style-fx::after {
  content: '';
  position: absolute;
  filter: blur(72px);
  border-radius: 50%;
  animation: fx-soft-a 32s ease-in-out infinite;
}

:root:not([data-style]) .style-fx::before,
:root[data-style='soft'] .style-fx::before {
  width: 48vw;
  height: 48vw;
  left: -14vw;
  top: -16vw;
  background: radial-gradient(circle at 42% 42%, rgba(92, 124, 250, 0.38), transparent 65%);
  opacity: 0.55;
}

:root:not([data-style]) .style-fx::after,
:root[data-style='soft'] .style-fx::after {
  width: 44vw;
  height: 44vw;
  right: -12vw;
  bottom: -16vw;
  background: radial-gradient(circle at 55% 45%, rgba(139, 92, 246, 0.3), transparent 62%);
  border-radius: 55% 45% 42% 58% / 50% 55% 45% 50%;
  animation: fx-soft-b 36s ease-in-out infinite;
  opacity: 0.45;
}

:root:not([data-style]) .card,
:root:not([data-style]) .admin-panel,
:root[data-style='soft'] .card,
:root[data-style='soft'] .admin-panel {
  border-radius: 20px;
}

@keyframes fx-soft-a {
  0%, 100% { transform: translate(0, 0) scale(1); }
  50% { transform: translate(3vw, 2vw) scale(1.06); }
}

@keyframes fx-soft-b {
  0%, 100% { transform: translate(0, 0) scale(1); }
  50% { transform: translate(-3vw, -2vw) scale(0.96); }
}

:root:not([data-style]) .style-fx::before,
:root:not([data-style]) .style-fx::after,
:root[data-style='soft'] .style-fx::before,
:root[data-style='soft'] .style-fx::after {
  content: '';
  position: absolute;
  filter: blur(72px);
  border-radius: 50%;
  animation: fx-soft-a 32s ease-in-out infinite;
}

:root:not([data-style]) .style-fx::before,
:root[data-style='soft'] .style-fx::before {
  width: 48vw;
  height: 48vw;
  left: -14vw;
  top: -16vw;
  background: radial-gradient(circle at 42% 42%, rgba(92, 124, 250, 0.38), transparent 65%);
  opacity: 0.55;
}

:root:not([data-style]) .style-fx::after,
:root[data-style='soft'] .style-fx::after {
  width: 44vw;
  height: 44vw;
  right: -12vw;
  bottom: -16vw;
  background: radial-gradient(circle at 55% 45%, rgba(139, 92, 246, 0.3), transparent 62%);
  border-radius: 55% 45% 42% 58% / 50% 55% 45% 50%;
  animation: fx-soft-b 36s ease-in-out infinite;
  opacity: 0.45;
}

:root:not([data-style]) .card,
:root:not([data-style]) .admin-panel,
:root[data-style='soft'] .card,
:root[data-style='soft'] .admin-panel {
  border-radius: 20px;
}

@property --aurora-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

[data-style='aurora'] .style-fx::before,
[data-style='aurora'] .style-fx::after {
  content: '';
  position: absolute;
  inset: -28%;
  pointer-events: none;
  will-change: transform, opacity;
  background-repeat: no-repeat;
}

[data-style='aurora'] .style-fx::before {
  filter: blur(76px) saturate(160%);
  opacity: 0.85;
  animation: aurora-drift-a 26s ease-in-out infinite alternate;
}

[data-style='aurora'] .style-fx::after {
  filter: blur(44px) saturate(150%);
  opacity: 0.7;
  transform-origin: 50% 0;
  animation: aurora-drift-b 19s ease-in-out infinite alternate;
}

[data-style='aurora'] .style-fx::before {
  background:
    radial-gradient(46vw 26vw at 14% 4%, rgba(0, 201, 255, 0.46) 0%, rgba(0, 201, 255, 0) 70%),
    radial-gradient(50vw 24vw at 84% 8%, rgba(123, 47, 247, 0.34) 0%, rgba(123, 47, 247, 0) 72%),
    radial-gradient(52vw 28vw at 98% 58%, rgba(0, 210, 150, 0.40) 0%, rgba(0, 210, 150, 0) 74%),
    radial-gradient(44vw 26vw at 30% 92%, rgba(255, 92, 190, 0.30) 0%, rgba(255, 92, 190, 0) 72%),
    radial-gradient(60vw 34vw at 60% 26%, rgba(80, 255, 158, 0.22) 0%, rgba(80, 255, 158, 0) 76%);
}

[data-style='aurora'] .style-fx::after {
  background:
    repeating-linear-gradient(102deg, rgba(0, 201, 255, 0.28) 0 1.4%, rgba(0, 201, 255, 0) 1.4% 6%),
    repeating-linear-gradient(86deg, rgba(0, 210, 150, 0.24) 0 1.8%, rgba(0, 210, 150, 0) 1.8% 8.5%),
    radial-gradient(70vw 40vw at 50% 0%, rgba(123, 47, 247, 0.26), rgba(123, 47, 247, 0) 78%);
  -webkit-mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.9) 0%, rgba(0, 0, 0, 0.5) 45%, transparent 84%);
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.9) 0%, rgba(0, 0, 0, 0.5) 45%, transparent 84%);
}

:root[data-theme='dark'][data-style='aurora'] .style-fx::before,
:root[data-theme='dark'][data-style='aurora'] .style-fx::after {
  mix-blend-mode: screen;
  opacity: 0.92;
}

:root[data-theme='dark'][data-style='aurora'] .style-fx::before {
  background:
    radial-gradient(48vw 26vw at 12% 2%, rgba(0, 255, 200, 0.62) 0%, rgba(0, 255, 200, 0) 70%),
    radial-gradient(52vw 24vw at 86% 6%, rgba(123, 47, 247, 0.58) 0%, rgba(123, 47, 247, 0) 72%),
    radial-gradient(54vw 30vw at 100% 56%, rgba(0, 184, 255, 0.55) 0%, rgba(0, 184, 255, 0) 74%),
    radial-gradient(46vw 26vw at 28% 94%, rgba(255, 92, 200, 0.46) 0%, rgba(255, 92, 200, 0) 72%),
    radial-gradient(64vw 34vw at 58% 24%, rgba(80, 255, 158, 0.34) 0%, rgba(80, 255, 158, 0) 76%);
}

:root[data-theme='dark'][data-style='aurora'] .style-fx::after {
  background:
    repeating-linear-gradient(104deg, rgba(0, 255, 200, 0.30) 0 1.2%, rgba(0, 255, 200, 0) 1.2% 5.4%),
    repeating-linear-gradient(82deg, rgba(0, 184, 255, 0.26) 0 1.8%, rgba(0, 184, 255, 0) 1.8% 8%),
    radial-gradient(72vw 42vw at 50% 0%, rgba(123, 47, 247, 0.42), rgba(123, 47, 247, 0) 80%);
}

@keyframes aurora-drift-a {
  0% { transform: translate3d(-4%, -2%, 0) rotate(-3deg) scale(1.12); }
  50% { transform: translate3d(3%, 2%, 0) rotate(2deg) scale(1.26); }
  100% { transform: translate3d(-1%, 3%, 0) rotate(-4deg) scale(1.16); }
}

@keyframes aurora-drift-b {
  0% { transform: translate3d(-3%, 1%, 0) skewX(-5deg) scaleY(1.06); opacity: 0.5; }
  50% { transform: translate3d(4%, 3%, 0) skewX(6deg) scaleY(1.22); opacity: 0.9; }
  100% { transform: translate3d(0%, -2%, 0) skewX(-3deg) scaleY(1.12); opacity: 0.62; }
}

[data-style='aurora'] .search-box {
  background: var(--surface);
  border: 1px solid var(--edge);
  border-radius: 18px;
  box-shadow: var(--raised-sm);
  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
}

@keyframes aurora-line {
  to { background-position: 220% 0; }
}

[data-style='aurora'] .search-box {
  border-radius: 16px;
}

[data-style='aurora'] .search-box:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft), 0 0 26px -8px var(--accent-glow);
}

[data-style='aurora'] .card {
  border-radius: 16px;
  background: var(--surface);
  border: 1px solid var(--edge);
  box-shadow: var(--raised-sm), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(20px) saturate(140%);
  -webkit-backdrop-filter: blur(20px) saturate(140%);
  isolation: isolate;
  transition: transform 240ms var(--ease), box-shadow 240ms var(--ease), border-color 240ms var(--ease);
}

[data-style='aurora'] .card::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background: radial-gradient(320px 240px at var(--px, 50%) var(--py, 0%), rgba(0, 255, 200, 0.3) 0%, rgba(0, 184, 255, 0.22) 40%, rgba(123, 47, 247, 0.16) 68%, rgba(123, 47, 247, 0) 85%);
  opacity: 0;
  transition: opacity 300ms var(--ease);
  pointer-events: none;
}

[data-style='aurora'] .card::before {
  content: '';
  position: absolute;
  inset: -1px;
  z-index: 2;
  border-radius: inherit;
  padding: 1.5px;
  background: conic-gradient(from var(--aurora-angle), rgba(0, 255, 200, 0), rgba(0, 255, 200, 0.95), rgba(0, 184, 255, 0.95), rgba(123, 47, 247, 0.95), rgba(255, 92, 200, 0.9), rgba(0, 255, 200, 0));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask-composite: exclude;
  opacity: 0.42;
  transition: opacity 260ms var(--ease);
  pointer-events: none;
}

[data-style='aurora'] .card:hover {
  transform: translateY(-4px);
  border-color: transparent;
  box-shadow: var(--raised-lg), 0 0 38px -8px var(--accent-glow);
}

[data-style='aurora'] .card:hover::before {
  opacity: 1;
  animation: aurora-spin 3.6s linear infinite;
}

[data-style='aurora'] .card:hover::after {
  opacity: 1;
}

[data-style='aurora'] .card:active {
  transform: translateY(0) scale(0.99);
  box-shadow: var(--pressed-sm);
}

@keyframes aurora-spin {
  to { --aurora-angle: 360deg; }
}

[data-style='aurora'] .card .icon {
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(0, 255, 200, 0.9), rgba(0, 184, 255, 0.9) 55%, rgba(123, 47, 247, 0.9));
  color: #ffffff;
}

:root[data-theme='dark'][data-style='aurora'] .card .icon {
  color: #02100d;
}

[data-style='aurora'] .group,
[data-style='aurora'] .group-parent {
  background: transparent;
  border: 1px solid var(--edge-weak);
  border-radius: 20px;
  box-shadow: none;
}

[data-style='aurora'] .group:hover,
[data-style='aurora'] .group-parent:hover {
  transform: none;
  box-shadow: none;
}

[data-style='aurora'] .group-head h2 {
  color: var(--text);
  text-shadow: 0 0 22px var(--accent-glow);
}

[data-style='aurora'] .group-parent-head {
  background: transparent;
  border: none;
  box-shadow: none;
  padding-left: 0;
}

[data-style='aurora'] .group-parent-head:hover {
  transform: none;
  box-shadow: none;
}

[data-style='aurora'] .group-parent-head h3 {
  background: linear-gradient(100deg, #00ffc8, #00b8ff, #7b2ff7, #ff5cc8);
  -webkit-text-fill-color: transparent;
  color: transparent;
  text-shadow: none;
}

:root[data-theme='light'][data-style='aurora'] .group-parent-head h3 {
  background-image: linear-gradient(100deg, #0b8f7d, #0077b6, #6d28d9, #c2185b);
}

[data-style='aurora'] .group-child {
  background: transparent;
  border: none;
  border-left: 2px solid var(--accent);
  border-radius: 14px;
  box-shadow: none;
}

[data-style='aurora'] .group-child .group-head h2 {
  text-shadow: 0 0 16px var(--accent-glow);
}

[data-style='aurora'] .clock-time {
  background: linear-gradient(100deg, #00ffc8, #00d4ff, #7b2ff7, #ff5cc8, #00ffc8);
  background-size: 300% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  text-shadow: none;
  filter: drop-shadow(0 0 26px var(--accent-glow));
  animation: aurora-text 9s linear infinite;
}

:root[data-theme='light'][data-style='aurora'] .clock-time {
  background-image: linear-gradient(100deg, #0b8f7d, #0077b6, #6d28d9, #c2185b, #0b8f7d);
  filter: drop-shadow(0 0 18px rgba(11, 143, 125, 0.35));
}

@keyframes aurora-text {
  to { background-position: 300% 0; }
}

[data-style='aurora'] .btn-primary,
[data-style='aurora'] .search-box .search-btn {
  background-color: var(--accent);
  background-image: linear-gradient(110deg, var(--accent), #00d9ff 50%, var(--accent));
  background-size: 220% 100%;
  animation: aurora-sheen 6s linear infinite;
  color: var(--on-accent);
  box-shadow: 0 8px 22px -10px var(--accent-glow);
}

@keyframes aurora-sheen {
  to { background-position: 220% 0; }
}

[data-style='aurora'] .btn:hover {
  transform: translateY(-1px);
  box-shadow: var(--raised), 0 0 22px -6px var(--accent-glow);
}

[data-style='aurora'] .btn:active {
  transform: scale(0.98);
}

[data-style='aurora'] .nm-item.active .nm-face,
[data-style='aurora'] .group-nav li.active-top > a {
  background-image: linear-gradient(135deg, var(--accent), #00b8ff);
  border-color: transparent;
  color: var(--on-accent);
}

[data-style='aurora'] .gn-dot {
  box-shadow: 0 0 10px var(--accent-glow);
}

[data-style='aurora'] .group-nav,
[data-style='aurora'] .engine-menu,
[data-style='aurora'] .search-history-dropdown,
[data-style='aurora'] .card-context-menu,
[data-style='aurora'] .modal-box,
[data-style='aurora'] .toast {
  border-radius: 16px;
  border: 1px solid var(--edge);
  background: var(--surface);
  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
}

[data-style='aurora'] .btn-primary:hover,
[data-style='aurora'] .search-box .search-btn:hover {
  box-shadow: 0 12px 30px -10px var(--accent-glow);
}

[data-style='aurora'] .card:focus-visible,
[data-style='aurora'] .btn:focus-visible {
  box-shadow: 0 0 0 3px var(--accent-soft), 0 0 20px -6px var(--accent-glow);
}

@media (prefers-reduced-motion: reduce) {
  [data-style='aurora'] *,
  [data-style='aurora'] *::before,
  [data-style='aurora'] *::after {
    animation: none !important;
    transition-duration: 1ms !important;
  }
}

[data-style='blueprint'] .style-fx::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(22, 50, 79, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(22, 50, 79, 0.05) 1px, transparent 1px),
    linear-gradient(rgba(22, 50, 79, 0.10) 1px, transparent 1px),
    linear-gradient(90deg, rgba(22, 50, 79, 0.10) 1px, transparent 1px);
  background-size: 8px 8px, 8px 8px, 40px 40px, 40px 40px;
  pointer-events: none;
}

:root[data-theme='dark'][data-style='blueprint'] .style-fx::before {
  background-image:
    linear-gradient(rgba(234, 243, 255, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(234, 243, 255, 0.04) 1px, transparent 1px),
    linear-gradient(rgba(234, 243, 255, 0.09) 1px, transparent 1px),
    linear-gradient(90deg, rgba(234, 243, 255, 0.09) 1px, transparent 1px);
  background-size: 8px 8px, 8px 8px, 40px 40px, 40px 40px;
}

[data-style='blueprint'] .glass {
  background: rgba(251, 252, 253, 0.62);
  border: 1px solid var(--edge);
  border-radius: 0;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}
[data-style='blueprint'] .glass:hover { transform: none; box-shadow: none; }

[data-style='blueprint'] .card {
  position: relative;
  border-radius: 0;
  border: 1px solid var(--edge);
  background: var(--surface);
  box-shadow: none;
  transition: border-color 110ms linear, background 110ms linear;
  counter-increment: bp-card;
}

[data-style='blueprint'] .card:hover {
  transform: none;
  border-color: var(--accent);
  box-shadow: none;
  background: var(--surface);
}

[data-style='blueprint'] .card .icon {
  width: 40px;
  height: 40px;
  border-radius: 0;
  border: 1px solid var(--edge);
  background: transparent;
  color: var(--accent);
  font-family: ui-monospace, 'SF Mono', Consolas, Menlo, monospace;
  font-size: 14px;
  box-shadow: none;
}
[data-style='blueprint'] .card:hover .icon { background: transparent; color: var(--accent); }

[data-style='blueprint'] .cards { counter-reset: bp-card; }
[data-style='blueprint'] .card::after {
  content: 'REF ' counter(bp-card, decimal-leading-zero);
  position: absolute;
  right: 8px;
  bottom: 4px;
  font-family: ui-monospace, 'SF Mono', Consolas, Menlo, monospace;
  font-size: 9px;
  letter-spacing: 0.18em;
  color: var(--annotation);
  opacity: 0.85;
  pointer-events: none;
}
[data-style='blueprint'] .card::before {
  content: '';
  position: absolute;
  top: -1px;
  left: -1px;
  width: 8px;
  height: 8px;
  border-top: 1px solid var(--annotation);
  border-left: 1px solid var(--annotation);
  opacity: 0.75;
  pointer-events: none;
}

[data-style='blueprint'] .group-head {
  padding-bottom: 10px;
  margin-bottom: 16px;
  border-bottom: 1px dashed var(--edge-weak);
  position: relative;
}
[data-style='blueprint'] .group-head::before {
  content: 'SECTION';
  align-self: center;
  padding-right: 8px;
  border-right: 1px solid var(--annotation);
  font-family: ui-monospace, 'SF Mono', Consolas, Menlo, monospace;
  font-size: 9.5px;
  letter-spacing: 0.22em;
  color: var(--annotation);
}

[data-style='blueprint'] .group-head h2 {
  font-size: 13.5px;
  font-weight: 700;
  letter-spacing: 0.14em;
}
[data-style='blueprint'] .group-head .desc {
  font-size: 11.5px;
  letter-spacing: 0.08em;
}
[data-style='blueprint'] .group-head .desc::before { content: '| '; color: var(--annotation); }

[data-style='blueprint'] .clock-time { font-size: 56px; font-weight: 600; letter-spacing: 8px; }
@media (max-width: 768px) {
  [data-style='blueprint'] .clock-time { font-size: 44px; letter-spacing: 4px; }
}

:root[data-theme='light'][data-style='blueprint'] .ntab-btn.active {
  background: var(--accent);
  color: var(--on-accent);
  border-color: var(--accent);
  box-shadow: none;
}

[data-style='blueprint'] .btn {
  border-radius: 0;
  border: 1px solid var(--accent);
  background: transparent;
  color: var(--text);
  font-family: ui-monospace, 'SF Mono', Consolas, Menlo, monospace;
  letter-spacing: 0.05em;
  transition: background 100ms linear, border-color 100ms linear, color 100ms linear;
}

[data-style='blueprint'] .btn:hover {
  background: var(--accent);
  color: #ffffff;
  box-shadow: none;
}

[data-style='blueprint'] .btn:active {
  transform: none;
  background: var(--annotation);
  color: #fff;
}

[data-style='blueprint'] .btn-primary {
  border-color: var(--accent);
  background: var(--accent);
  color: #ffffff;
}

:root[data-theme='dark'][data-style='blueprint'] .btn:hover {
  background: var(--accent);
  color: #0a1c33;
}

:root[data-theme='dark'][data-style='blueprint'] .btn-primary {
  background: var(--accent);
  color: #0a1c33;
}

[data-style='blueprint'] .input,
[data-style='blueprint'] .select,
[data-style='blueprint'] .textarea {
  border-radius: 0;
  border: 1px solid var(--edge);
  background: transparent;
  color: var(--text);
  font-family: ui-monospace, 'SF Mono', Consolas, Menlo, monospace;
  box-shadow: none;
}

[data-style='blueprint'] .input:focus,
[data-style='blueprint'] .select:focus,
[data-style='blueprint'] .textarea:focus {
  border-color: var(--annotation);
  box-shadow: none;
}

:root[data-theme='dark'][data-style='blueprint'] .select,
:root[data-theme='dark'][data-style='blueprint'] .select option {
  background: #0d2440;
  color: #ffffff;
}

[data-style='blueprint'] h1,
[data-style='blueprint'] h2,
[data-style='blueprint'] h3,
[data-style='blueprint'] .section-title,
[data-style='blueprint'] .group-title {
  font-family: ui-monospace, 'SF Mono', Consolas, Menlo, monospace;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

[data-style='blueprint'] .divider,
[data-style='blueprint'] hr {
  border: none;
  border-top: 1px dashed var(--edge-weak);
  background: none;
}

[data-style='blueprint'] .annotation,
[data-style='blueprint'] .accent-tag,
[data-style='blueprint'] .badge-accent {
  color: var(--annotation);
}

[data-style='blueprint'] .badge {
  border-radius: 0;
  border: 1px solid var(--edge);
  font-family: ui-monospace, 'SF Mono', Consolas, Menlo, monospace;
}

[data-style='blueprint'] table th,
[data-style='blueprint'] table td {
  border: 1px solid var(--edge-weak);
  font-family: ui-monospace, 'SF Mono', Consolas, Menlo, monospace;
}

[data-style='blueprint'] .admin-panel {
  border-radius: 0;
  border: 1px solid var(--edge);
  background: var(--surface);
}

[data-style='blueprint'] .modal-box {
  border-radius: 0;
  border: 1px solid var(--edge);
  background: var(--surface);
  box-shadow: var(--raised-lg);
}

[data-style='blueprint'] .avatar,
[data-style='blueprint'] .avatar img,
[data-style='blueprint'] .profile-avatar {
  border-radius: 0 !important;
  border: 1px solid var(--edge);
}

[data-style='blueprint'] .selected,
[data-style='blueprint'] .active-tab,
[data-style='blueprint'] .nav-item.active {
  border-left: 2px solid var(--annotation);
  padding-left: 10px;
}

[data-style='blueprint'] .search-box .search-btn,
[data-style='blueprint'] .hotnews-btn.active,
[data-style='blueprint'] .ntab-btn.active,
